import { Link } from 'react-router-dom';
import { ChevronRight, Home, LayoutDashboard } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useEffect } from 'react';

export interface BreadcrumbItem {
  label: string;
  href?: string;
}

interface BreadcrumbFirstItem {
  label: string;
  href: string;
  icon?: 'home' | 'dashboard';
}

interface PageBreadcrumbProps {
  items: BreadcrumbItem[];
  /** 自定义首项（替代默认的 Home），传 null 则不显示首项 */
  firstItem?: BreadcrumbFirstItem | null;
  className?: string;
  /** 是否注入 Schema.org BreadcrumbList JSON-LD（默认 true） */
  schemaId?: string;
}

/**
 * 可复用页面面包屑组件
 * - 首项默认 Home 图标+文字，可通过 firstItem 自定义（或传 null 隐藏）
 * - 非末项可点击跳转
 * - 末项为当前页，不可点击，用 text-foreground 高亮
 * - 深色工业风格，与整站主题一致
 */
export default function PageBreadcrumb({ items, firstItem, className, schemaId }: PageBreadcrumbProps) {
  const showFirst = firstItem !== null;
  const defaultFirst: BreadcrumbFirstItem = firstItem ?? { label: 'Home', href: '/', icon: 'home' };
  const FirstIcon = defaultFirst.icon === 'dashboard' ? LayoutDashboard : Home;

  // 注入 BreadcrumbList Schema.org JSON-LD
  useEffect(() => {
    const id = schemaId || 'breadcrumb-schema';
    const allItems: { name: string; href?: string }[] = showFirst
      ? [{ name: defaultFirst.label, href: defaultFirst.href }, ...items.map((i) => ({ name: i.label, href: i.href }))]
      : items.map((i) => ({ name: i.label, href: i.href }));

    const schema = {
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: allItems.map((item, idx) => {
        const entry: Record<string, unknown> = {
          '@type': 'ListItem',
          position: idx + 1,
          name: item.name,
        };
        if (item.href) {
          let fullUrl = item.href;
          if (typeof window !== 'undefined' && item.href.startsWith('/')) {
            fullUrl = `${window.location.origin}${item.href}`;
          }
          entry.item = fullUrl;
        }
        return entry;
      }),
    };

    let el = document.getElementById(id) as HTMLScriptElement | null;
    if (!el) {
      el = document.createElement('script');
      el.type = 'application/ld+json';
      el.id = id;
      document.head.appendChild(el);
    }
    el.textContent = JSON.stringify(schema);

    return () => {
      // 组件卸载时不移除，因为同一页可能多个面包屑；由 useSeo 统一管理页面级 schema
    };
  }, [items, firstItem, showFirst, defaultFirst.label, defaultFirst.href, schemaId]);

  return (
    <nav aria-label="Breadcrumb" className={cn('w-full', className)}>
      <ol className="flex flex-wrap items-center gap-1.5 sm:gap-2 text-sm text-muted-foreground">
        {showFirst && (
          <li className="inline-flex items-center gap-1.5">
            <Link
              to={defaultFirst.href}
              className="inline-flex items-center gap-1 hover:text-foreground transition-colors"
            >
              <FirstIcon className="size-3.5" />
              <span className="hidden sm:inline">{defaultFirst.label}</span>
            </Link>
          </li>
        )}
        {items.map((item, idx) => {
          const isLast = idx === items.length - 1;
          const showSeparator = showFirst || idx > 0;
          return (
            <li key={idx} className="inline-flex items-center gap-1.5 min-w-0">
              {showSeparator && <ChevronRight className="size-3.5 shrink-0 opacity-60" />}
              {item.href && !isLast ? (
                <Link
                  to={item.href}
                  className="hover:text-foreground transition-colors truncate"
                >
                  {item.label}
                </Link>
              ) : (
                <span
                  className={cn(
                    'truncate max-w-[240px]',
                    isLast ? 'text-foreground font-medium' : 'text-muted-foreground',
                  )}
                  aria-current={isLast ? 'page' : undefined}
                >
                  {item.label}
                </span>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
